      publishA: '지갑의 스크립트와 참여자 이름을 트랜잭션의 메타데이터(CIP-146)에 기록해요. 그러면 나중에 자기 키가 들어 있는 사람은 누구나 체인에서 그 지갑을 찾을 수 있어요. 일반 트랜잭션 수수료가 들고, 게시하는 사람이 내요. 새로 만든 공유 지갑에는 아무것도 없어서 스스로 낼 수 없거든요.',
      searchQ: '체인을 검색하면 무엇을 찾나요?',
      searchA: '당신의 키 중 하나를 명시한 게시 등록을 찾아요. 새 휴대폰에서, 또는 아직 그 지갑에 속해 있는지 확실하지 않을 때 유용해요. 지갑이 존재한다는 것과 누가 들어 있는지는 알려주지만, 지갑을 다시 만들지는 못해요. 등록에는 스크립트만 있고 공동 서명자들의 키는 없거든요. 참여자 누구에게든 구성을 보내 달라고 하세요.',
      lostQ: '공동 서명자가 지갑을 잃어버렸어요. 어떻게 하나요?',
